"use client";

import {
  Bar,
  BarChart as RBarChart,
  CartesianGrid,
  Cell,
  LabelList,
  Rectangle,
  Tooltip,
  XAxis,
  YAxis,
  type BarShapeProps,
} from "recharts";
import { BAND_CURSOR, CATEGORY_AXIS, GRID, TICK, VALUE_AXIS, TOOLTIP_MOTION } from "./cartesian";
import { ChartFrame, type ChartBaseProps, type LegendItem } from "./ChartFrame";
import { ChartTooltip } from "./ChartTooltip";
import { formatNumber } from "./format";
import { colorOf, maxOf, niceTicks, numberAt, resolveSeries, type ChartRow, type SeriesOrConfig } from "./scale";

export type BarChartProps = ChartBaseProps & {
  data: ReadonlyArray<ChartRow>;
  /** Field holding the category (region, team member, week, stage). */
  category: string;
  /**
   * columns = vertical bars, for time and short labels.
   * bars    = horizontal, for many or long-named categories (regions, team members).
   */
  orientation?: "columns" | "bars";
  /** Parts of a whole per category. */
  stacked?: boolean;
  /**
   * One colour per category, for ordered categories on a single series (a
   * funnel's stages, from ordinalColors). Nominal categories never get this:
   * one series is one colour.
   */
  categoryColors?: ReadonlyArray<string>;
  formatCategory?: (value: string) => string;
  formatCategoryLong?: (value: string) => string;
  formatValue?: (value: number) => string;
  categoryLabel?: string;
  /** Value at each bar's end. Default: on for a single unstacked series. */
  valueLabels?: boolean;
  /** Fixed value-axis top, e.g. 5 for places per team member. */
  max?: number;
  /** Width reserved for horizontal-bar category labels. */
  categoryWidth?: number;
  tooltipTag?: string;
} & SeriesOrConfig;

/** Mark spec: never thicker than 24px, whatever the slot allows. */
const MAX_BAR = 24;

export function BarChart({
  data,
  category,
  series: seriesProp,
  config,
  orientation = "columns",
  stacked = false,
  categoryColors,
  formatCategory = String,
  formatCategoryLong,
  formatValue = formatNumber,
  categoryLabel = "Category",
  valueLabels,
  max,
  categoryWidth = 150,
  tooltipTag,
  height,
  ...base
}: BarChartProps) {
  const series = resolveSeries({ series: seriesProp, config });
  const horizontal = orientation === "bars";
  const plotHeight = height ?? (horizontal ? Math.max(120, data.length * 36 + 30) : 248);
  const ticks = niceTicks(max ?? maxOf(data, series, stacked), horizontal ? 5 : 4);
  const top = ticks[ticks.length - 1];
  const single = series.length === 1 && !stacked;
  const showValues = valueLabels ?? single;

  const legend: LegendItem[] = series.map((s, i) => ({ key: s.key, label: s.label, color: colorOf(s, i), shape: "rect" }));

  return (
    <ChartFrame
      {...base}
      height={plotHeight}
      skeleton={horizontal ? "bars" : "columns"}
      legend={legend}
      isEmpty={data.length === 0}
      table={{
        rowHeader: { key: category, label: categoryLabel, format: (v) => (formatCategoryLong ?? formatCategory)(String(v)) },
        columns: series.map((s) => ({ key: s.key, label: s.label, numeric: true, format: (v) => formatValue(Number(v ?? 0)) })),
        rows: data,
        totals: stacked || series.length > 1,
      }}
    >
      {({ width, markRadius: r }) => {
        // 4px rounded data-end, square at the baseline; square when the theme zeroes the radius.
        const end: [number, number, number, number] = horizontal ? [0, r, r, 0] : [r, r, 0, 0];
        // Only the outermost non-zero segment of a stack gets the rounded end,
        // so a row whose last series is 0 still ends round. Hover lightens.
        const shapeFor = (i: number, active: boolean) =>
          function BarShape(p: BarShapeProps) {
            const row = (p.payload ?? {}) as ChartRow;
            const outer = !stacked || series.slice(i + 1).every((s) => numberAt(row, s.key) <= 0);
            return (
              <Rectangle
                x={p.x}
                y={p.y}
                width={p.width}
                height={p.height}
                fill={p.fill}
                stroke={p.stroke}
                strokeWidth={p.strokeWidth}
                radius={outer ? end : 0}
                fillOpacity={active ? 0.82 : 1}
              />
            );
          };
        // Columns: a tick per bar where they fit, else every nth, evenly.
        const every = Math.max(0, Math.ceil((data.length * 52) / Math.max(1, width - 60)) - 1);
        const valueAxis = (
          <XAxis
            type="number"
            {...VALUE_AXIS}
            domain={[0, top]}
            ticks={ticks}
            tickFormatter={(v) => formatValue(Number(v))}
          />
        );
        return (
          <RBarChart
            width={width}
            height={plotHeight}
            data={data as ChartRow[]}
            layout={horizontal ? "vertical" : "horizontal"}
            margin={{ top: 12, right: showValues ? 36 : 12, bottom: 0, left: 0 }}
            barCategoryGap={horizontal ? "30%" : "28%"}
            barGap={2}
            desc={base.summary}
            accessibilityLayer
          >
            <CartesianGrid horizontal={!horizontal} vertical={horizontal} {...GRID} />
            {horizontal ? (
              <>
                {valueAxis}
                <YAxis
                  type="category"
                  dataKey={category}
                  width={categoryWidth}
                  tickLine={false}
                  axisLine={{ stroke: "var(--chart-axis)" }}
                  tick={{ ...TICK, fill: "var(--chart-label)" }}
                  tickFormatter={(v) => formatCategory(String(v))}
                  interval={0}
                />
              </>
            ) : (
              <>
                <XAxis
                  dataKey={category}
                  {...CATEGORY_AXIS}
                  tickFormatter={(v) => formatCategory(String(v))}
                  interval={every}
                />
                <YAxis
                  {...VALUE_AXIS}
                  domain={[0, top]}
                  ticks={ticks}
                  width={Math.max(28, formatValue(top).length * 7 + 8)}
                  tickFormatter={(v) => formatValue(Number(v))}
                />
              </>
            )}
            <Tooltip
              cursor={BAND_CURSOR}
              {...TOOLTIP_MOTION}
              content={(p) => (
                <ChartTooltip
                  {...p}
                  series={series}
                  formatLabel={formatCategoryLong ?? formatCategory}
                  formatValue={formatValue}
                  tag={tooltipTag}
                  total={stacked}
                />
              )}
            />
            {series.map((s, i) => {
              const color = colorOf(s, i);
              return (
                <Bar
                  key={s.key}
                  dataKey={s.key}
                  name={s.label}
                  fill={color}
                  stackId={stacked ? "stack" : undefined}
                  maxBarSize={MAX_BAR}
                  // The 2px surface gap between stacked segments.
                  stroke={stacked ? "var(--chart-gap)" : undefined}
                  strokeWidth={stacked ? 2 : 0}
                  shape={shapeFor(i, false)}
                  activeBar={shapeFor(i, true)}
                >
                  {categoryColors && single
                    ? data.map((row, j) => <Cell key={String(row[category])} fill={categoryColors[j] ?? color} />)
                    : null}
                  {showValues ? (
                    <LabelList
                      dataKey={s.key}
                      position={horizontal ? "right" : "top"}
                      offset={6}
                      fontSize={11}
                      fontWeight={700}
                      fill="var(--chart-value)"
                      formatter={(v) => formatValue(Number(v ?? 0))}
                    />
                  ) : null}
                </Bar>
              );
            })}
          </RBarChart>
        );
      }}
    </ChartFrame>
  );
}

import { cx } from "@/components/ui/_internal/cx";
import { ChartLegend, type LegendItem } from "./ChartFrame";
import styles from "./Charts.module.css";
import { formatNumber, formatPercent } from "./format";

export type CapacitySegment = {
  key: string;
  label: string;
  value: number;
  /** A var() from palette.ts. The remainder always takes the track colour. */
  color: string;
};

export type CapacityBarProps = {
  /** The limit: 400 program places. */
  total: number;
  /** Filled segments, in order from the start of the track. */
  segments: ReadonlyArray<CapacitySegment>;
  /** Names what the unfilled remainder is ("Behind invited or unallocated seats"). */
  remainderLabel: string;
  /** Spoken summary; the track itself is an image. */
  label: string;
  className?: string;
};

/**
 * One limit, split into the quantities that use it. Earns its place over
 * Meter where a single fill would hide the story: 400 places are not just
 * used or free, they are used, open under an active team member, or not yet
 * usable because the seat is unallocated. Segments meet on the 2px surface
 * gap; the legend carries every number, so colour never works alone.
 */
export function CapacityBar({ total, segments, remainderLabel, label, className }: CapacityBarProps) {
  const used = segments.reduce((n, s) => n + s.value, 0);
  const remainder = Math.max(0, total - used);
  const items: LegendItem[] = [
    ...segments.map((s) => ({
      key: s.key,
      label: s.label,
      color: s.color,
      shape: "rect" as const,
      value: `${formatNumber(s.value)} · ${formatPercent(s.value / total)}`,
    })),
    {
      key: "remainder",
      label: remainderLabel,
      color: "var(--chart-track)",
      shape: "rect" as const,
      value: `${formatNumber(remainder)} · ${formatPercent(remainder / total)}`,
    },
  ];

  return (
    <div className={cx(styles.tokens, styles.capacity, className)}>
      <div className={styles.capacityTrack} role="img" aria-label={label}>
        {segments.map((s) =>
          s.value > 0 ? (
            <span key={s.key} className={styles.capacitySeg} style={{ flexGrow: s.value, flexBasis: 0, background: s.color }} />
          ) : null,
        )}
        {remainder > 0 ? (
          <span className={styles.capacitySeg} style={{ flexGrow: remainder, flexBasis: 0, background: "var(--chart-track)" }} />
        ) : null}
      </div>
      <div className={styles.capacityScale} aria-hidden="true">
        <span>0</span>
        <span>{formatNumber(total)}</span>
      </div>
      <ChartLegend items={items} />
    </div>
  );
}

"use client";

import type { LabelProps } from "recharts";
import { numberAt, type ChartRow, type ChartSeries } from "./scale";

// Shared axis, grid and label specs for the Cartesian charts. Spread as
// props rather than wrapped in components so Recharts sees its own children.

/** Tick text: 11px, the muted ink (5.2:1 on glass), tabular via CSS. */
export const TICK = { fill: "var(--chart-tick)", fontSize: 11 } as const;

/** The category axis: a hairline baseline, no tick marks. */
export const CATEGORY_AXIS = {
  tickLine: false,
  axisLine: { stroke: "var(--chart-axis)" },
  tick: TICK,
  tickMargin: 8,
} as const;

/** The value axis: no line at all, the gridlines carry it. */
export const VALUE_AXIS = {
  tickLine: false,
  axisLine: false,
  tick: TICK,
  tickMargin: 6,
  allowDecimals: false,
} as const;

/** Recessive grid: solid hairlines one step off the surface, never dashed. */
export const GRID = { stroke: "var(--chart-grid)", strokeDasharray: undefined } as const;

/** Recharts' default x-axis band. */
export const X_AXIS_HEIGHT = 30;

/** Crosshair on line and area: a hairline that snaps to the nearest x. */
export const CROSSHAIR = { stroke: "var(--chart-cursor)", strokeWidth: 1 } as const;

/** Bars: a faint band behind the hovered category; the mark is the target. */
export const BAND_CURSOR = { fill: "var(--chart-band)" } as const;

/**
 * Tooltip motion: Recharts' defaults, which is what shadcn ships. While the
 * tooltip is active Recharts sets `transition: transform 400ms ease` on the
 * wrapper, so the box glides between points. "auto" turns it off under
 * prefers-reduced-motion and during SSR. Never pass isAnimationActive={false}.
 */
export const TOOLTIP_MOTION = {
  isAnimationActive: "auto",
  animationDuration: 400,
  animationEasing: "ease",
} as const;

/** Dots and end-markers wear a 2px ring in the surface colour. */
export function activeDot(color: string) {
  return { r: 4, fill: color, stroke: "var(--chart-gap)", strokeWidth: 2 } as const;
}

const LABEL_CHAR_PX = 6.2;
const MIN_LABEL_GAP_PX = 14;

/** Right margin that fits the end labels, capped so a long name cannot eat the plot. */
export function endLabelMargin(series: ReadonlyArray<ChartSeries>, valueWidth = 22): number {
  const longest = Math.max(...series.map((s) => (s.shortLabel ?? s.label).length));
  return Math.min(150, Math.round(longest * LABEL_CHAR_PX + valueWidth + 14));
}

/**
 * Direct end labels work only where series separate at the right edge. The
 * domain is set from niceTicks, so each end's pixel height is known before
 * render; if any two land closer than a line of text, labels are off and the
 * legend plus tooltip carry identity (nudging them apart would detach them).
 */
export function endLabelsFit(
  rows: ReadonlyArray<ChartRow>,
  series: ReadonlyArray<ChartSeries>,
  top: number,
  plotHeight: number,
): boolean {
  if (!rows.length || series.length > 4) return false;
  const last = rows[rows.length - 1];
  const ys = series.map((s) => (numberAt(last, s.key) / top) * plotHeight).sort((a, b) => a - b);
  return ys.every((y, i) => i === 0 || y - ys[i - 1] >= MIN_LABEL_GAP_PX);
}

/** Renders a label at the last point only: the value, then the series name. */
export function endLabel(lastIndex: number, name: string, format: (n: number) => string) {
  function EndLabel(props: LabelProps) {
    const { index, value, viewBox } = props;
    if (index !== lastIndex || !viewBox || !("x" in viewBox)) return null;
    const x = Number(viewBox.x ?? 0);
    const y = Number(viewBox.y ?? 0);
    return (
      <text x={x + 9} y={y} dy="0.35em" fontSize={11} fill="var(--chart-value)" fontWeight={700}>
        {format(Number(value ?? 0))}
        <tspan dx={5} fontWeight={400} fill="var(--chart-label)">
          {name}
        </tspan>
      </text>
    );
  }
  return EndLabel;
}

"use client";

import { useEffect, useId, useState, type ReactNode, type CSSProperties } from "react";
import { Button } from "@/components/ui/Button/Button";
import { IconAlertCircle, IconInbox, IconRefresh } from "@/components/ui/Icon/Icon";
import { Skeleton } from "@/components/ui/Skeleton/Skeleton";
import { SegmentedControl } from "@/components/ui/Tabs/Tabs";
import { cx } from "@/components/ui/_internal/cx";
import styles from "./Charts.module.css";
import type { ChartRow } from "./scale";

/**
 * ready      = draw it.
 * loading    = first load: a skeleton shaped like this chart.
 * refreshing = refetch: keep the last render at reduced opacity, no skeleton flash.
 * empty      = nothing to plot; say what will fill it.
 * error      = the query failed; say so and offer a retry.
 */
export type ChartStatus = "ready" | "loading" | "refreshing" | "empty" | "error";

export type SkeletonShape = "line" | "area" | "columns" | "bars" | "donut";

export type LegendItem = {
  key: string;
  label: string;
  color: string;
  /** Mirrors the mark: line for lines, rect for bars and areas. */
  shape: "line" | "rect" | "dot";
  value?: ReactNode;
};

export type TableColumn = {
  key: string;
  label: string;
  numeric?: boolean;
  format?: (value: ChartRow[string]) => string;
};

export type ChartTableSpec = {
  /** The row header column (dates, regions, stages). */
  rowHeader: TableColumn;
  columns: ReadonlyArray<TableColumn>;
  rows: ReadonlyArray<ChartRow>;
  /** Adds a totals row summing every numeric column. */
  totals?: boolean;
};

/** Props every chart takes: its caption, accessible summary and states. */
export type ChartBaseProps = {
  title: ReactNode;
  subtitle?: ReactNode;
  /**
   * One or two sentences a screen reader hears in place of the picture:
   * what is plotted and the headline ("Weekly orders rose from 8 to 32").
   * Also set as the SVG's <desc>.
   */
  summary: string;
  /** Keeps the title for assistive tech but hides it, when a Group heading already says it. */
  hideTitle?: boolean;
  status?: ChartStatus;
  emptyTitle?: ReactNode;
  /** What to do next, or what will fill this. A bare "No data" is not an empty state. */
  emptyDescription?: ReactNode;
  emptyAction?: ReactNode;
  errorTitle?: ReactNode;
  errorDescription?: ReactNode;
  onRetry?: () => void;
  /** Controls placed beside the table toggle (a segmented control, a menu). */
  actions?: ReactNode;
  /** Plot height in px, x-axis band included. */
  height?: number;
  className?: string;
};

type Measure = { width: number; markRadius: number };

type ChartFrameProps = ChartBaseProps & {
  skeleton: SkeletonShape;
  legend?: ReadonlyArray<LegendItem>;
  table: ChartTableSpec;
  isEmpty: boolean;
  height: number;
  /** Height is a floor, not a size: content beside the plot may wrap below it (donut legend). */
  grow?: boolean;
  children: (measure: Measure) => ReactNode;
};

/**
 * The container every chart mounts in: caption, legend, the plot and its
 * table-view twin, and the loading, refreshing, empty and error states.
 *
 * The plot is measured, not guessed: nothing renders into it until a
 * ResizeObserver reports a width, so the server and first client render agree
 * (no hydration mismatch) and Recharts never sees a zero-size container. The
 * same read picks up --r-2xs, so bar ends are 4px in the portal and square in
 * any theme without its radius living in JS.
 */
export function ChartFrame({
  title,
  subtitle,
  summary,
  hideTitle,
  status = "ready",
  emptyTitle = "Nothing to chart yet",
  emptyDescription = "Figures appear here as soon as the first records for this period are in.",
  emptyAction,
  errorTitle = "This chart could not load",
  errorDescription = "The figures are safe; only this view failed. Try again, or refresh the page if it keeps happening.",
  onRetry,
  actions,
  className,
  skeleton,
  legend,
  table,
  isEmpty,
  height,
  grow,
  children,
}: ChartFrameProps) {
  const id = useId();
  const [showTable, setShowTable] = useState(false);
  const [node, setNode] = useState<HTMLDivElement | null>(null);
  const [measure, setMeasure] = useState<Measure>({ width: 0, markRadius: 4 });

  useEffect(() => {
    if (!node) return;
    const observer = new ResizeObserver(([entry]) => {
      const width = Math.floor(entry.contentRect.width);
      const radius = parseFloat(getComputedStyle(node).getPropertyValue("--r-2xs"));
      setMeasure((m) => {
        const markRadius = Number.isFinite(radius) ? radius : 4;
        return m.width === width && m.markRadius === markRadius ? m : { width, markRadius };
      });
    });
    observer.observe(node);
    return () => observer.disconnect();
  }, [node]);

  const effective: ChartStatus = status === "ready" && isEmpty ? "empty" : status;
  const drawable = effective === "ready" || effective === "refreshing";
  const tableOn = showTable && drawable;

  let body: ReactNode;
  if (effective === "loading") {
    body = <ChartSkeleton shape={skeleton} />;
  } else if (effective === "error") {
    body = (
      <div className={cx(styles.state, styles.stateError)} role="alert">
        <span className={styles.stateIcon} aria-hidden="true">
          <IconAlertCircle size={17} />
        </span>
        <p className={styles.stateTitle}>{errorTitle}</p>
        <p className={styles.stateBody}>{errorDescription}</p>
        {onRetry ? (
          <div className={styles.stateAction}>
            <Button variant="secondary" size="sm" iconStart={<IconRefresh size={14} />} onClick={onRetry}>
              Try again
            </Button>
          </div>
        ) : null}
      </div>
    );
  } else if (effective === "empty") {
    body = (
      <>
        {skeleton === "donut" ? null : <span className={styles.ghostAxes} aria-hidden="true" />}
        <div className={cx(styles.state, styles.stateOver)}>
          <span className={styles.stateIcon} aria-hidden="true">
            <IconInbox size={17} />
          </span>
          <p className={styles.stateTitle}>{emptyTitle}</p>
          <p className={styles.stateBody}>{emptyDescription}</p>
          {emptyAction ? <div className={styles.stateAction}>{emptyAction}</div> : null}
        </div>
      </>
    );
  } else if (measure.width > 0) {
    body = children(measure);
  } else {
    // Unmeasured (server render, first paint): the chart's own silhouette.
    body = <ChartSkeleton shape={skeleton} />;
  }

  return (
    <figure
      className={cx(styles.tokens, styles.root, className)}
      aria-labelledby={`${id}-t`}
      aria-describedby={`${id}-s`}
      style={colorVars(legend)}
    >
      <div className={styles.head}>
        <figcaption className={cx(styles.caption, hideTitle && "sr-only")}>
          <span id={`${id}-t`} className={styles.title}>
            {title}
          </span>
          {subtitle ? <span className={styles.subtitle}>{subtitle}</span> : null}
        </figcaption>
        <div className={styles.headActions}>
          {actions}
          {/* A real two-way toggle: Chart | Table, the same
              control as the other view switches, not a button that relabels itself. */}
          {drawable ? (
            <SegmentedControl<"chart" | "table">
              size="sm"
              aria-label={`View ${typeof title === "string" ? title : "this chart"} as`}
              value={tableOn ? "table" : "chart"}
              onChange={(v) => setShowTable(v === "table")}
              options={[
                { value: "chart", label: "Chart" },
                { value: "table", label: "Table" },
              ]}
            />
          ) : null}
        </div>
      </div>
      <p id={`${id}-s`} className="sr-only">
        {summary}
      </p>

      {legend && legend.length > 1 && drawable && !tableOn ? <ChartLegend items={legend} /> : null}

      {tableOn ? (
        <ChartTable spec={table} caption={typeof title === "string" ? title : undefined} />
      ) : (
        <div
          ref={setNode}
          className={cx(styles.plot, effective === "refreshing" && styles.refreshing)}
          style={grow ? { minHeight: height } : { height }}
          aria-busy={effective === "loading" || effective === "refreshing" || undefined}
        >
          {effective === "loading" ? <span className="sr-only">Loading {typeof title === "string" ? title : "chart"}</span> : null}
          {body}
        </div>
      )}
    </figure>
  );
}

// ── Legend ───────────────────────────────────────────────────────────────

/** Always present for two or more series. Text wears ink; the key carries the colour. */
export function ChartLegend({ items, className }: { items: ReadonlyArray<LegendItem>; className?: string }) {
  return (
    <ul className={cx(styles.legend, className)}>
      {items.map((item) => (
        <li key={item.key} className={styles.legendItem}>
          <LegendKey color={item.color} shape={item.shape} />
          <span>{item.label}</span>
          {item.value !== undefined ? <span className={styles.legendValue}>{item.value}</span> : null}
        </li>
      ))}
    </ul>
  );
}

export function LegendKey({ color, shape }: { color: string; shape: LegendItem["shape"] }) {
  const cls = shape === "line" ? styles.keyLine : shape === "dot" ? styles.keyDot : styles.keyRect;
  return <span className={cls} style={{ background: color }} aria-hidden="true" />;
}

// ── Table view ───────────────────────────────────────────────────────────

function cell(column: TableColumn, value: ChartRow[string]): string {
  if (column.format) return column.format(value);
  if (typeof value === "number") return new Intl.NumberFormat("en-AU").format(value);
  return value === null || value === undefined ? "–" : String(value);
}

/** The chart's WCAG-clean twin: every value, no hover required. */
export function ChartTable({ spec, caption }: { spec: ChartTableSpec; caption?: string }) {
  const { rowHeader, columns, rows, totals } = spec;
  const sums = totals
    ? columns.map((c) => (c.numeric ? rows.reduce((n, r) => n + (typeof r[c.key] === "number" ? (r[c.key] as number) : 0), 0) : null))
    : null;
  return (
    <div className={styles.tableWrap}>
      <table className={styles.table}>
        {caption ? <caption className="sr-only">{caption}</caption> : null}
        <thead>
          <tr>
            <th scope="col">{rowHeader.label}</th>
            {columns.map((c) => (
              <th key={c.key} scope="col" className={c.numeric ? styles.num : undefined}>
                {c.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, i) => (
            <tr key={`${String(row[rowHeader.key])}-${i}`}>
              <th scope="row">{cell(rowHeader, row[rowHeader.key])}</th>
              {columns.map((c) => (
                <td key={c.key} className={c.numeric ? styles.num : undefined}>
                  {cell(c, row[c.key])}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
        {sums ? (
          <tfoot>
            <tr>
              <th scope="row">Total</th>
              {columns.map((c, i) => (
                <td key={c.key} className={c.numeric ? styles.num : undefined}>
                  {sums[i] === null ? "" : cell({ ...c, format: undefined }, sums[i])}
                </td>
              ))}
            </tr>
          </tfoot>
        ) : null}
      </table>
    </div>
  );
}

// ── Skeletons: the chart's silhouette ────────────────────────────────────

const COLUMN_HEIGHTS = [38, 54, 47, 68, 60, 82, 74, 90];
const BAR_WIDTHS = [92, 78, 66, 54, 41, 30];

export function ChartSkeleton({ shape }: { shape: SkeletonShape }) {
  if (shape === "donut") {
    return (
      <div className={styles.skDonut} aria-hidden="true">
        <span className={styles.skRing} style={{ width: 150, height: 150 }} />
        <span className={styles.skLegend}>
          {[70, 56, 64].map((w) => (
            <Skeleton key={w} variant="text" height={11} width={`${w}%`} />
          ))}
        </span>
      </div>
    );
  }
  if (shape === "bars") {
    return (
      <div className={styles.skBarsH} aria-hidden="true">
        {BAR_WIDTHS.map((w, i) => (
          <span key={w} className={styles.skBarRowH}>
            <Skeleton variant="text" height={10} width={`${70 + ((i * 13) % 30)}%`} />
            <Skeleton height={14} width={`${w}%`} radius={4} />
          </span>
        ))}
      </div>
    );
  }
  return (
    <div className={styles.skeleton} aria-hidden="true">
      <span className={styles.skYTicks}>
        {[0, 1, 2, 3, 4].map((i) => (
          <Skeleton key={i} variant="text" height={8} width={i === 4 ? 8 : 20} />
        ))}
      </span>
      <span className={styles.skPlot}>
        {shape === "columns" ? (
          COLUMN_HEIGHTS.map((h, i) => <Skeleton key={i} width={20} height={`${h}%`} radius={4} />)
        ) : (
          <svg className={styles.skLine} viewBox="0 0 100 100" preserveAspectRatio="none">
            {shape === "area" ? <path className={styles.skArea} d="M0 92 C 18 84, 30 70, 48 58 S 78 26, 100 12 L 100 100 L 0 100 Z" /> : null}
            <path
              d={
                shape === "area"
                  ? "M0 92 C 18 84, 30 70, 48 58 S 78 26, 100 12"
                  : "M0 78 C 10 70, 18 64, 28 66 S 44 50, 56 52 S 74 30, 84 36 S 96 22, 100 20"
              }
            />
          </svg>
        )}
      </span>
      <span className={styles.skXTicks}>
        {[0, 1, 2, 3, 4, 5].map((i) => (
          <Skeleton key={i} variant="text" height={8} width={28} />
        ))}
      </span>
    </div>
  );
}

/**
 * Carries the chart tokens for a chart piece rendered on its own (a tooltip
 * or legend specimen) outside a chart root.
 */
export function ChartScope({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={cx(styles.tokens, className)}>{children}</div>;
}

/**
 * --color-<key> for each series, on the chart root, as shadcn's
 * ChartContainer does: custom marks added inside a high-level chart can use
 * fill="var(--color-orders)" and follow the series colour.
 */
function colorVars(legend: ReadonlyArray<LegendItem> | undefined): CSSProperties | undefined {
  if (!legend?.length) return undefined;
  const vars: Record<string, string> = {};
  for (const item of legend) if (/^[w-]+$/.test(item.key)) vars[`--color-${item.key}`] = item.color;
  return vars as CSSProperties;
}

/* shadcn-shaped chart primitives (ChartContainer, ChartTooltipContent,
   ChartLegendContent) drawn with Rime's tokens. Pairs with primitives.tsx.
   Nothing here carries a hex: the palette (--chart-1..6) lives in
   tokens.css and the chrome (--chart-grid, --chart-tick, --chart-cursor,
   --chart-band) in Charts.module.css .tokens, which ChartContainer applies. */

/* ── Container ─────────────────────────────────────────────────────────── */

.container {
  position: relative;
  display: flex;
  justify-content: center;
  min-width: 0;
  aspect-ratio: 16 / 9;
  font-family: var(--font-body);
  font-size: var(--text-caption);
  color: var(--ink-body);
}

/* Recharts ships grey (#ccc / #fff) chrome. These are the same overrides
   shadcn's ChartContainer applies with Tailwind arbitrary variants, written
   as :global selectors scoped under the container. */
.container :global(.recharts-cartesian-axis-tick text) {
  fill: var(--chart-tick, var(--ink-muted));
}

.container :global(.recharts-cartesian-grid line[stroke="#ccc"]) {
  stroke: var(--chart-grid, var(--line-soft));
}

.container :global(.recharts-polar-grid [stroke="#ccc"]),
.container :global(.recharts-reference-line [stroke="#ccc"]) {
  stroke: var(--chart-axis, var(--line));
}

/* Line and area crosshair: a quiet hairline. */
.container :global(.recharts-curve.recharts-tooltip-cursor) {
  stroke: var(--chart-cursor, var(--line));
}

/* Bar cursor: a faint band behind the hovered category. */
.container :global(.recharts-rectangle.recharts-tooltip-cursor) {
  fill: var(--chart-band, var(--wash-hover));
}

.container :global(.recharts-radial-bar-background-sector) {
  fill: var(--surface-sunken);
}

.container :global(.recharts-dot[stroke="#fff"]),
.container :global(.recharts-sector[stroke="#fff"]) {
  stroke: transparent;
}

/* accessibilityLayer makes the surface focusable; the kit's focus ring is
   drawn by the chart frame, not by a browser outline on an SVG layer. */
.container :global(.recharts-surface),
.container :global(.recharts-layer),
.container :global(.recharts-sector) {
  outline: none;
}

/* ── Tooltip content ───────────────────────────────────────────────────── */

/* The surface is the kit's popover glass: frosted in Default, opaque in
   Flat, deep glass in Dark, all from tokens. Compact like shadcn's
   (min 8rem, 12px text, 6px by 10px padding) so it glides rather than
   lurches: a small box moving 400ms reads as motion, a big one reads as lag. */
.tooltip {
  display: grid;
  gap: 6px;
  min-width: 8rem;
  max-width: 280px;
  padding: 6px 10px;
  border: 1px solid var(--popover-border, transparent);
  border-radius: var(--r-md);
  background: var(--popover-surface, var(--surface-solid));
  box-shadow: var(--popover-shadow, var(--shadow-float));
  -webkit-backdrop-filter: var(--popover-blur, none);
  backdrop-filter: var(--popover-blur, none);
  font-size: var(--text-caption);
  line-height: 1.2;
  color: var(--ink-body);
  pointer-events: none;
}

.label {
  font-weight: 600;
  color: var(--ink-heading);
}

.tag {
  margin-left: 6px;
  padding: 1px 5px;
  border-radius: var(--r-2xs);
  background: var(--wash-active);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: var(--tracking-label);
  text-transform: uppercase;
  color: var(--ink-brand);
}

.rows {
  display: grid;
  gap: 6px;
}

.row {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  gap: 8px;
  width: 100%;
}

.row[data-indicator="dot"] {
  align-items: center;
}

.row > svg {
  width: 10px;
  height: 10px;
  color: var(--ink-muted);
}

.rowBody {
  display: flex;
  flex: 1;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  line-height: 1;
}

.rowBody[data-nested="true"] {
  align-items: flex-end;
}

.rowText {
  display: grid;
  gap: 6px;
}

.name {
  color: var(--ink-muted);
}

/* Values: the strong element, tabular so a column of them lines up while
   the box glides. */
.value {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.01em;
  color: var(--ink-heading);
}

/* ── Indicators: dot, line, dashed (the shadcn set) ────────────────────── */

.indicator {
  flex-shrink: 0;
  border: 0 solid var(--indicator);
  border-radius: 2px;
  background: var(--indicator);
}

.indicator[data-shape="dot"] {
  width: 10px;
  height: 10px;
}

.indicator[data-shape="line"] {
  width: 4px;
}

.indicator[data-shape="dashed"] {
  width: 0;
  border-width: 1.5px;
  border-style: dashed;
  background: transparent;
}

.indicator[data-shape="dashed"][data-nested="true"] {
  margin: 2px 0;
}

/* Optional total row (stacked charts): a hairline, then the sum. */
.total {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  margin-top: 2px;
  padding-top: 6px;
  border-top: 1px solid var(--line-soft);
  font-weight: 600;
  color: var(--ink-heading);
}

.total .value {
  font-weight: 700;
}

/* ── Legend content ────────────────────────────────────────────────────── */

.legend {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 6px 16px;
  font-size: var(--text-caption);
  color: var(--ink-secondary);
}

.legend[data-align="top"] {
  padding-bottom: 12px;
}

.legend[data-align="bottom"] {
  padding-top: 12px;
}

.legendItem {
  display: flex;
  align-items: center;
  gap: 6px;
}

.legendItem > svg {
  width: 12px;
  height: 12px;
  color: var(--ink-muted);
}

.legendSwatch {
  flex-shrink: 0;
  width: 8px;
  height: 8px;
  border-radius: 2px;
}

/* Chart layer. The palette (--chart-1..6, --chart-other, --chart-seq-*,
   --chart-good|warning|danger) lives in app/styles/tokens.css at :root, so
   the Studio, the presets, dark mode and the shadcn aliases all see it.
   Hexes mirror palette.ts: change both together. .tokens, which every chart
   root, stat strip, sparkline and capacity bar carries, holds only the
   chrome (grid, axis, ticks, gap, cursor), derived from the global tokens. */

.tokens {
  /* Chrome. Grid is one step off the surface, solid, never dashed. */
  --chart-grid: var(--line-glass);
  --chart-axis: var(--line);
  --chart-tick: var(--ink-muted);
  --chart-label: var(--ink-secondary);
  --chart-value: var(--ink-heading);
  /* The 2px separator between touching fills and the ring round markers:
     the surface colour doing the separating, not a drawn border. */
  --chart-gap: var(--surface-solid);
  --chart-cursor: rgba(var(--rgb-brand-deep), 0.3);
  --chart-band: var(--wash-hover);
  /* Unfilled track of a meter: a lighter step of the fill's own ramp. */
  --chart-track: rgba(var(--rgb-brand), 0.14);
}

/* The figure every Cartesian and donut chart mounts in. */
.root {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
  margin: 0;
}


/* ── Frame: head, legend, plot ───────────────────────────────────────── */

.head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.caption {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.title {
  font-size: var(--text-small);
  font-weight: 700;
  color: var(--ink-heading);
}

.subtitle {
  font-size: var(--text-caption);
  color: var(--ink-muted);
  text-wrap: pretty;
}

.headActions {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 8px;
}

/* "Table" / "Chart" toggle: a quiet text control, the chart is the content. */
.viewToggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 10px;
  border: 0;
  border-radius: var(--r-xs);
  background: transparent;
  font: inherit;
  font-size: var(--text-caption);
  font-weight: 700;
  color: var(--ink-muted);
  cursor: pointer;
  transition:
    background-color var(--dur) var(--ease),
    color var(--dur) var(--ease);
}

.viewToggle:hover {
  background: var(--wash-hover);
  color: var(--ink-heading);
}

.viewToggle:active {
  background: var(--wash-active);
}

.viewToggle:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.viewToggle[aria-pressed="true"] {
  background: var(--wash-active);
  color: var(--ink-heading);
}

.viewToggle:disabled {
  color: var(--ink-disabled);
  background: transparent;
  cursor: default;
}

.plot {
  position: relative;
  min-width: 0;
  transition: opacity var(--dur-slow) var(--ease);
}

/* Refetch keeps the frame: the last render holds at reduced opacity. */
.refreshing {
  opacity: 0.45;
  pointer-events: none;
}

/* ── Legend ────────────────────────────────────────────────────────── */

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 16px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.legendItem {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: var(--text-caption);
  color: var(--chart-label);
}

.legendValue {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--chart-value);
}

/* Keys mirror the mark: a short stroke for lines, a small block for fills. */
.keyLine {
  width: 14px;
  height: 2px;
  flex-shrink: 0;
  border-radius: 1px;
}

.keyRect {
  width: 10px;
  height: 10px;
  flex-shrink: 0;
  border-radius: var(--r-flat, 2px);
}

.keyDot {
  width: 8px;
  height: 8px;
  flex-shrink: 0;
  border-radius: var(--r-circle, 50%);
}

/* ── Recharts surface ─────────────────────────────────────────────────── */

.plot :global(.recharts-surface) {
  overflow: visible;
}

/* Keyboard focus lands on the SVG (Recharts' accessibility layer: arrow keys
   walk the data points). The global :focus-visible outline already applies;
   this rounds it to the plot and keeps it inside the frame. */
.plot :global(.recharts-surface:focus-visible) {
  outline: 2px solid var(--brand);
  outline-offset: 2px;
  border-radius: var(--r-xs);
}

.plot :global(.recharts-cartesian-axis-tick-value),
.plot :global(.recharts-label),
.plot :global(.recharts-text) {
  font-family: var(--font-body);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.plot :global(.recharts-tooltip-wrapper) {
  z-index: 2;
  outline: none;
}

/* ── Tooltip: the overlay surface ───────────────────────────────────── */

/* shadcn's compact tooltip on the kit's popover glass: frosted in Default,
   opaque in Flat, deep glass in Dark. Small, so the 400ms glide reads as
   following the pointer rather than lagging it. */
.tooltip {
  display: grid;
  gap: 6px;
  min-width: 8rem;
  max-width: 280px;
  padding: 6px 10px;
  border: 1px solid var(--popover-border);
  border-radius: var(--r-md);
  background: var(--popover-surface);
  -webkit-backdrop-filter: var(--popover-blur);
  backdrop-filter: var(--popover-blur);
  box-shadow: var(--popover-shadow);
  pointer-events: none;
  font-family: var(--font-body);
  font-size: var(--text-caption);
}

.tooltipHead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  font-weight: 700;
  color: var(--ink-heading);
}

.tooltipTag {
  padding: 0 5px;
  border-radius: var(--r-2xs);
  background: var(--wash-active);
  font-size: 10px;
  font-weight: 700;
  color: var(--ink-brand);
}

.tooltipRows {
  display: grid;
  gap: 4px;
  margin: 0;
}

.tooltipRow {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
}

.tooltipRow dt {
  overflow: hidden;
  color: var(--ink-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tooltipRow dd {
  margin: 0;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  text-align: right;
  color: var(--ink-heading);
}

/* Indicators, as shadcn: dot, line (mirrors a stroke) or dashed. */
.tooltipKey {
  flex-shrink: 0;
  border: 0 solid var(--indicator);
  border-radius: 2px;
  background: var(--indicator);
}

.tooltipKey[data-shape="dot"] {
  width: 10px;
  height: 10px;
}

.tooltipKey[data-shape="line"] {
  width: 4px;
  height: 14px;
}

.tooltipKey[data-shape="dashed"] {
  width: 0;
  height: 14px;
  border-width: 1.5px;
  border-style: dashed;
  background: transparent;
}

.tooltipFoot {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin: 0;
  padding-top: 5px;
  border-top: 1px solid var(--line-soft);
  color: var(--ink-muted);
}

.tooltipFoot strong {
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--ink-heading);
}

/* ── Table view: the WCAG-clean twin of every chart ───────────────────── */

.tableWrap {
  overflow-x: auto;
  border-radius: var(--r-md);
  background: var(--glass-fill-nested);
  box-shadow: inset 0 0 0 1px var(--line-glass);
}

.table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--text-small);
}

.table th,
.table td {
  padding: var(--table-cell-pad);
  text-align: left;
  white-space: nowrap;
}

.table thead th {
  padding: var(--table-head-pad);
  background: var(--table-head-fill);
  border-bottom: var(--table-head-rule);
  font-size: var(--text-caption);
  font-weight: 700;
  color: var(--table-head-ink);
}

.table tbody tr {
  transition: background-color var(--dur) var(--ease);
}

.table tbody tr:hover {
  background: var(--table-row-hover);
}

.table tbody th {
  font-weight: 700;
  color: var(--ink-body);
}

.table td {
  color: var(--ink-body);
}

.table tbody tr + tr > * {
  border-top: var(--table-row-line);
}

.num {
  text-align: right !important;
  font-variant-numeric: tabular-nums;
}

.table tfoot th,
.table tfoot td {
  border-top: 2px solid var(--line-glass);
  font-weight: 800;
  color: var(--ink-heading);
}

/* ── States ─────────────────────────────────────────────────────────── */

.state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 100%;
  padding: 16px 24px;
  border-radius: var(--r-md);
  box-shadow: inset 0 0 0 1px var(--line-glass);
  text-align: center;
}

.stateIcon {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  margin-bottom: 4px;
  border-radius: var(--r-sm);
  background: var(--wash-subtle);
  color: var(--ink-brand);
}

.stateError .stateIcon {
  background: var(--danger-fill);
  color: var(--danger-ink);
}

.stateTitle {
  font-size: var(--text-small);
  font-weight: 700;
  color: var(--ink-heading);
}

.stateBody {
  max-width: 44ch;
  font-size: var(--text-caption);
  color: var(--ink-muted);
  text-wrap: pretty;
}

.stateAction {
  margin-top: 8px;
}

/* Ghost axes behind the empty message, so the empty chart still reads as the
   chart it will become. */
.ghostAxes {
  position: absolute;
  inset: 8px 8px 28px 44px;
  pointer-events: none;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0,
    transparent calc(25% - 1px),
    var(--chart-grid) calc(25% - 1px),
    var(--chart-grid) 25%
  );
  border-bottom: 1px solid var(--chart-axis);
  opacity: 0.8;
  /* Clear behind the message so no gridline runs through the text. */
  -webkit-mask-image: linear-gradient(to right, #000 0, transparent 22%, transparent 78%, #000 100%);
  mask-image: linear-gradient(to right, #000 0, transparent 22%, transparent 78%, #000 100%);
}

.stateOver {
  position: relative;
  z-index: 1;
  box-shadow: none;
}

/* ── Skeletons: shaped like the chart, not a grey block ───────────────── */

.skeleton {
  position: relative;
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr);
  grid-template-rows: minmax(0, 1fr) 22px;
  gap: 6px 10px;
  height: 100%;
}

.skYTicks {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: space-between;
  padding: 2px 0;
}

.skPlot {
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: space-around;
  gap: 8px;
  padding: 0 4px;
  border-bottom: 1px solid var(--chart-axis);
  background: repeating-linear-gradient(
    to bottom,
    transparent 0,
    transparent calc(25% - 1px),
    var(--chart-grid) calc(25% - 1px),
    var(--chart-grid) 25%
  );
}

.skXTicks {
  grid-column: 2;
  display: flex;
  justify-content: space-between;
  padding: 0 4px;
}

.skLine {
  position: absolute;
  inset: 8% 0 0;
  width: 100%;
  height: 92%;
  overflow: visible;
}

.skLine path {
  fill: none;
  stroke: rgba(var(--rgb-brand-deep), 0.12);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
  animation: skPulse 1.6s var(--ease) infinite;
}

.skLine .skArea {
  fill: rgba(var(--rgb-brand-deep), 0.05);
  stroke: none;
}

.skBarsH {
  display: flex;
  flex-direction: column;
  justify-content: space-around;
  gap: 10px;
  height: 100%;
}

.skBarRowH {
  display: grid;
  grid-template-columns: 30% minmax(0, 1fr);
  align-items: center;
  gap: 10px;
}

.skDonut {
  display: flex;
  align-items: center;
  gap: 24px;
  height: 100%;
}

.skRing {
  flex-shrink: 0;
  border-radius: var(--r-circle, 50%);
  border: 18px solid rgba(var(--rgb-brand-deep), 0.075);
  animation: skPulse 1.6s var(--ease) infinite;
}

.skLegend {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 12px;
}

@keyframes skPulse {
  50% {
    opacity: 0.55;
  }
}

@media (prefers-reduced-motion: reduce) {
  .skLine path,
  .skRing {
    animation: none;
  }
}

/* ── Donut ───────────────────────────────────────────────────────────── */

.donut {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 16px 28px;
}

.donutPlot {
  position: relative;
  flex-shrink: 0;
}

.donutCentre {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  text-align: center;
}

.donutTotal {
  font-size: 26px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.03em;
  color: var(--ink-heading);
}

.donutTotalLabel {
  margin-top: 4px;
  font-size: var(--text-micro);
  font-weight: 700;
  letter-spacing: var(--tracking-label);
  text-transform: uppercase;
  color: var(--ink-muted);
}

/* The donut's legend carries every value and share, so no segment needs a
   label on the ring and the tooltip never gates a number. */
.donutLegend {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 180px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.donutLegend li {
  display: grid;
  grid-template-columns: 10px minmax(0, 1fr) auto 44px;
  align-items: center;
  gap: 10px;
  padding: 7px 0;
  font-size: var(--text-small);
  color: var(--chart-label);
}

.donutLegend li + li {
  border-top: 1px solid var(--line-glass);
}

.donutValue {
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  text-align: right;
  color: var(--chart-value);
}

.donutShare {
  font-size: var(--text-caption);
  font-variant-numeric: tabular-nums;
  text-align: right;
  color: var(--ink-muted);
}

/* ── Sparkline ───────────────────────────────────────────────────────── */

.sparkline {
  display: block;
  overflow: visible;
}

.sparkline path {
  fill: none;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

/* ── Stat strip: one panel, hairline dividers, no card grid ─────────── */

.strip {
  display: grid;
  grid-template-columns: repeat(var(--stat-count, 4), minmax(0, 1fr));
  margin: 0;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  padding: 2px 20px;
}

.stat dd {
  margin: 0;
}

.statSkeleton {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.stat:first-child {
  padding-left: 0;
}

.stat:last-child {
  padding-right: 0;
}

.stat + .stat {
  border-left: 1px solid var(--line-glass);
}

/* Sentence case, never a small uppercase label over the figure. */
.statLabel {
  font-size: var(--text-small);
  font-weight: 700;
  color: var(--ink-muted);
}

/* Proportional figures at display size: tabular digits look loose here. */
.statValue {
  margin: 0;
  font-size: 28px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.03em;
  color: var(--ink-heading);
}

.statUnit {
  margin-left: 3px;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0;
  color: var(--ink-muted);
}

.statFoot {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 10px;
  min-height: 28px;
}

.delta {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: var(--text-caption);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.deltaGood {
  color: var(--success-ink);
}

.deltaBad {
  color: var(--danger-ink);
}

.deltaFlat {
  color: var(--ink-muted);
}

.deltaPeriod {
  font-weight: 400;
  color: var(--ink-muted);
}

@media (max-width: 860px) {
  .strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    row-gap: 18px;
  }

  .stat,
  .stat:first-child,
  .stat:last-child {
    padding: 2px 16px;
  }

  .stat:nth-child(odd) {
    padding-left: 0;
    border-left: 0;
  }
}

/* ── Capacity bar: one limit, three quantities ────────────────────────── */

.capacity {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.capacityTrack {
  display: flex;
  gap: 2px;
  height: 14px;
  overflow: hidden;
  border-radius: var(--r-2xs);
}

.capacitySeg {
  height: 100%;
  min-width: 2px;
}

.capacityScale {
  display: flex;
  justify-content: space-between;
  font-size: var(--text-micro);
  font-variant-numeric: tabular-nums;
  color: var(--ink-muted);
}

/* Recharts ships grey (#ccc / #fff) chrome. The same overrides shadcn's
   ChartContainer applies, for anything a consumer adds inside a chart. */
.root :global(.recharts-cartesian-axis-tick text) {
  fill: var(--chart-tick);
}

.root :global(.recharts-cartesian-grid line[stroke="#ccc"]) {
  stroke: var(--chart-grid);
}

.root :global(.recharts-polar-grid [stroke="#ccc"]),
.root :global(.recharts-reference-line [stroke="#ccc"]) {
  stroke: var(--chart-axis);
}

.root :global(.recharts-curve.recharts-tooltip-cursor) {
  stroke: var(--chart-cursor);
}

.root :global(.recharts-rectangle.recharts-tooltip-cursor) {
  fill: var(--chart-band);
}

.root :global(.recharts-radial-bar-background-sector) {
  fill: var(--surface-sunken);
}

.root :global(.recharts-dot[stroke="#fff"]),
.root :global(.recharts-sector[stroke="#fff"]) {
  stroke: transparent;
}

.root :global(.recharts-surface),
.root :global(.recharts-layer),
.root :global(.recharts-sector) {
  outline: none;
}

"use client";

import type { CSSProperties } from "react";
import type { TooltipContentProps } from "recharts";
import styles from "./Charts.module.css";
import { formatNumber } from "./format";
import { colorOf, type ChartSeries } from "./scale";

export type ChartTooltipOptions = {
  series: ReadonlyArray<ChartSeries>;
  /** Header: the x value, formatted in full ("Week of 23 Nov 2026"). */
  formatLabel?: (label: string) => string;
  formatValue?: (value: number) => string;
  /** Small uppercase tag in the header ("Cumulative"). */
  tag?: string;
  /** Adds a total row: stacked charts, where the sum is the question. */
  total?: boolean | string;
  /** Key beside each row, as shadcn: "dot" (bars, areas, the default), "line" (lines) or "dashed" (a forecast or reference series). */
  indicator?: "dot" | "line" | "dashed";
  /** Hide the label line (the x value). */
  hideLabel?: boolean;
};

/**
 * The one tooltip every Cartesian chart uses, in shadcn's compact layout:
 * the x value as a label line, then one row per series at that x (the
 * pointer never has to land on a line) as [indicator] name ... value, on the
 * popover glass. Recharts glides it between points (TOOLTIP_MOTION).
 * Enhances only: every value is also in the table view.
 */
export function ChartTooltip({
  active,
  payload,
  label,
  series,
  formatLabel,
  formatValue = formatNumber,
  tag,
  total,
  indicator = "dot",
  hideLabel,
}: Partial<TooltipContentProps> & ChartTooltipOptions) {
  if (!active || !payload?.length) return null;
  const header = label === undefined || label === null ? "" : String(label);

  // Keep the series' own order (the legend's), not the payload's.
  const rows = series
    .map((s, i) => {
      const entry = payload.find((p) => p.dataKey === s.key);
      return entry ? { key: s.key, label: s.label, color: colorOf(s, i), value: Number(entry.value ?? 0) } : null;
    })
    .filter((r): r is NonNullable<typeof r> => r !== null);

  const sum = rows.reduce((n, r) => n + r.value, 0);

  return (
    <div className={styles.tooltip}>
      {hideLabel ? null : (
        <div className={styles.tooltipHead}>
          <span>{formatLabel ? formatLabel(header) : header}</span>
          {tag ? <span className={styles.tooltipTag}>{tag}</span> : null}
        </div>
      )}
      <dl className={styles.tooltipRows}>
        {rows.map((r) => (
          <div key={r.key} className={styles.tooltipRow}>
            <span
              className={styles.tooltipKey}
              data-shape={indicator}
              style={{ "--indicator": r.color } as CSSProperties}
              aria-hidden="true"
            />
            <dt>{r.label}</dt>
            <dd>{formatValue(r.value)}</dd>
          </div>
        ))}
      </dl>
      {total && rows.length > 1 ? (
        <p className={styles.tooltipFoot}>
          <span>{typeof total === "string" ? total : "Total"}</span>
          <strong>{formatValue(sum)}</strong>
        </p>
      ) : null}
    </div>
  );
}

"use client";

import type { Key } from "react";
import { Cell, Pie, PieChart, Sector, Tooltip, type PieSectorDataItem, type TooltipContentProps } from "recharts";
import { ChartFrame, LegendKey, type ChartBaseProps } from "./ChartFrame";
import styles from "./Charts.module.css";
import { formatNumber, formatPercent } from "./format";
import { TOOLTIP_MOTION } from "./cartesian";
import { seriesColor } from "./palette";

export type DonutDatum = {
  key: string;
  label: string;
  value: number;
  /** Explicit colour: ordinalColors() for ordered classes (severity). Default: categorical slot. */
  color?: string;
};

export type DonutChartProps = Omit<ChartBaseProps, "height"> & {
  data: ReadonlyArray<DonutDatum>;
  /** Centre figure label, e.g. "Customers". The figure is the total. */
  centreLabel: string;
  /** Override the centre figure (defaults to the sum). */
  centreValue?: string;
  formatValue?: (value: number) => string;
  /** Ring diameter in px. */
  size?: number;
  categoryLabel?: string;
};

// Part-to-whole at a glance: five segments at most (fold the tail into
// "Other"), and close values belong in a bar chart. With three or fewer
// categorical slots the ends, which touch, are validated all-pairs.
const RING = 20;

type Slice = DonutDatum & { fill: string; share: number };

export function DonutChart({
  data,
  centreLabel,
  centreValue,
  formatValue = formatNumber,
  size = 168,
  categoryLabel = "Group",
  ...base
}: DonutChartProps) {
  const total = data.reduce((n, d) => n + d.value, 0);
  const slices: Slice[] = data.map((d, i) => ({
    ...d,
    fill: d.color ?? seriesColor(i),
    share: total > 0 ? d.value / total : 0,
  }));

  return (
    <ChartFrame
      {...base}
      height={size}
      grow
      skeleton="donut"
      isEmpty={total === 0}
      table={{
        rowHeader: { key: "label", label: categoryLabel },
        columns: [
          { key: "value", label: centreLabel, numeric: true, format: (v) => formatValue(Number(v ?? 0)) },
          { key: "share", label: "Share", numeric: true, format: (v) => formatPercent(Number(v ?? 0)) },
        ],
        rows: slices.map((s) => ({ label: s.label, value: s.value, share: s.share })),
      }}
    >
      {({ markRadius }) => (
        <div className={styles.donut}>
          <div className={styles.donutPlot} style={{ width: size, height: size }}>
            <PieChart width={size} height={size} margin={{ top: 0, right: 0, bottom: 0, left: 0 }} desc={base.summary} accessibilityLayer>
              <Pie
                data={slices}
                dataKey="value"
                nameKey="label"
                cx="50%"
                cy="50%"
                innerRadius={size / 2 - RING - 2}
                outerRadius={size / 2 - 2}
                startAngle={90}
                endAngle={-270}
                // The 2px surface gap between segments, not a drawn border.
                stroke="var(--chart-gap)"
                strokeWidth={2}
                cornerRadius={Math.min(markRadius, 2)}
                activeShape={(props: PieSectorDataItem) => {
                  // Recharts passes its React key inside the props; pass it
                  // directly rather than through the spread (React warns otherwise).
                  const { key, ...rest } = props as PieSectorDataItem & { key?: Key };
                  return <Sector key={key} {...rest} fillOpacity={0.82} />;
                }}
              >
                {slices.map((s) => (
                  <Cell key={s.key} fill={s.fill} />
                ))}
              </Pie>
              <Tooltip
                {...TOOLTIP_MOTION}
                content={(p) => <DonutTooltip {...p} formatValue={formatValue} />}
              />
            </PieChart>
            <div className={styles.donutCentre} aria-hidden="true">
              <span className={styles.donutTotal}>{centreValue ?? formatValue(total)}</span>
              <span className={styles.donutTotalLabel}>{centreLabel}</span>
            </div>
          </div>
          {/* Every value and share, so the ring needs no labels and the tooltip never gates. */}
          <ul className={styles.donutLegend}>
            {slices.map((s) => (
              <li key={s.key}>
                <LegendKey color={s.fill} shape="rect" />
                <span>{s.label}</span>
                <span className={styles.donutValue}>{formatValue(s.value)}</span>
                <span className={styles.donutShare}>{formatPercent(s.share)}</span>
              </li>
            ))}
          </ul>
        </div>
      )}
    </ChartFrame>
  );
}

function DonutTooltip({
  active,
  payload,
  formatValue,
}: Partial<TooltipContentProps> & { formatValue: (value: number) => string }) {
  const entry = payload?.[0];
  if (!active || !entry) return null;
  const slice = entry.payload as Slice;
  return (
    <div className={styles.tooltip}>
      <div className={styles.tooltipHead}>
        <span>{slice.label}</span>
      </div>
      <dl className={styles.tooltipRows}>
        <div className={styles.tooltipRow}>
          <span className={styles.tooltipKey} style={{ background: slice.fill }} aria-hidden="true" />
          <dt>{formatPercent(slice.share)} of total</dt>
          <dd>{formatValue(slice.value)}</dd>
        </div>
      </dl>
    </div>
  );
}

// en-AU number and date formatting for charts, ticks, tooltips and tables.
//
// Dates arrive as ISO calendar strings ("2026-11-23", "2026-11") and are
// formatted in UTC, so the server and the browser render the same label
// whatever the viewer's zone: a chart that hydrates must not shift a week.

const LOCALE = "en-AU";

const integer = new Intl.NumberFormat(LOCALE, { maximumFractionDigits: 0 });
const oneDecimal = new Intl.NumberFormat(LOCALE, { maximumFractionDigits: 1 });
const compact = new Intl.NumberFormat(LOCALE, { notation: "compact", maximumFractionDigits: 1 });

/** 1,284. Comma separated, no decimals. */
export function formatNumber(value: number | null | undefined): string {
  if (value === null || value === undefined || Number.isNaN(value)) return "–";
  return Math.abs(value) < 10 && !Number.isInteger(value) ? oneDecimal.format(value) : integer.format(value);
}

/** 1,284 / 12.9K / 4.2M. For stat values and crowded axes. */
export function formatCompact(value: number | null | undefined): string {
  if (value === null || value === undefined || Number.isNaN(value)) return "–";
  return Math.abs(value) < 10_000 ? integer.format(value) : compact.format(value);
}

/** A 0 to 1 ratio as a percentage: 0.625 -> "63%". */
export function formatPercent(ratio: number, digits = 0): string {
  if (!Number.isFinite(ratio)) return "–";
  return new Intl.NumberFormat(LOCALE, {
    style: "percent",
    maximumFractionDigits: digits,
    minimumFractionDigits: digits,
  }).format(ratio);
}

/** Signed change with a true minus sign: "+12", "−3", "0". */
export function formatDelta(value: number, format: (n: number) => string = formatNumber): string {
  if (value === 0) return format(0);
  return `${value > 0 ? "+" : "−"}${format(Math.abs(value))}`;
}

// ── Dates ──────────────────────────────────────────────────────────────────

/** "2026-11-23" or "2026-11" -> a UTC Date. */
export function parseIsoDate(iso: string): Date {
  const [y, m, d] = iso.split("-").map(Number);
  return new Date(Date.UTC(y, (m ?? 1) - 1, d ?? 1));
}

const dayShort = new Intl.DateTimeFormat(LOCALE, { day: "numeric", month: "short", timeZone: "UTC" });
const dayLong = new Intl.DateTimeFormat(LOCALE, { day: "numeric", month: "short", year: "numeric", timeZone: "UTC" });
const monthShort = new Intl.DateTimeFormat(LOCALE, { month: "short", timeZone: "UTC" });
const monthLong = new Intl.DateTimeFormat(LOCALE, { month: "long", year: "numeric", timeZone: "UTC" });

/** Axis tick for a day or week: "23 Nov". */
export function formatDay(iso: string): string {
  return dayShort.format(parseIsoDate(iso));
}

/** "23 Nov 2026". */
export function formatDate(iso: string): string {
  return dayLong.format(parseIsoDate(iso));
}

/** Tooltip header for a weekly bucket: "Week of 23 Nov 2026". */
export function formatWeekOf(iso: string): string {
  return `Week of ${formatDate(iso)}`;
}

/** Axis tick for a month: "Nov". */
export function formatMonthTick(iso: string): string {
  return monthShort.format(parseIsoDate(iso));
}

/** Tooltip header for a month: "November 2026". */
export function formatMonth(iso: string): string {
  return monthLong.format(parseIsoDate(iso));
}

