 */
const THEME_SELECTORS = {
  light: [""],
  dark: [".dark", '[data-mode="dark"]', '[data-theme="dark"]'],
  flat: ['[data-theme="flat"]'],
} as const;

type ThemeName = keyof typeof THEME_SELECTORS;

/**
 * One entry per series key (the dataKey, or the nameKey value for pies).
 * `color` is any CSS colour; prefer a palette slot ("var(--chart-1)") so the
 * series re-themes with the preset. `theme` is for the rare series whose
 * colour must differ per preset.
 */
export type ChartConfig = Record<
  string,
  {
    label?: ReactNode;
    icon?: ComponentType<{ className?: string }>;
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Partial<Record<ThemeName, string>> & { light: string } }
  )
>;

type ChartContextValue = { config: ChartConfig };

const ChartContext = createContext<ChartContextValue | null>(null);

export function useChart(): ChartContextValue {
  const ctx = useContext(ChartContext);
  if (!ctx) throw new Error("useChart must be used inside <ChartContainer>.");
  return ctx;
}

// ── Container ───────────────────────────────────────────────────────────

export type ChartContainerProps = Omit<ComponentProps<"div">, "children"> & {
  config: ChartConfig;
  /** One Recharts chart (AreaChart, BarChart...). */
  children: ComponentProps<typeof ResponsiveContainer>["children"];
  /** Size used before the first measure, so SSR and first paint are not 0 by 0. */
  initialDimension?: { width: number; height: number };
};

/**
 * Wraps one Recharts chart: provides the config, exposes each series colour
 * as --color-<key> on the wrapper, applies the chart tokens and the kit's
 * chrome overrides, and measures with ResponsiveContainer. Give it a height
 * (style={{ height: 240 }}) or keep the default 16:9 aspect ratio.
 */
export function ChartContainer({
  id,
  config,
  className,
  style,
  children,
  initialDimension = { width: 320, height: 200 },
  ...rest
}: ChartContainerProps) {
  const uid = useId();
  const chartId = `chart-${(id ?? uid).replace(/[^a-zA-Z0-9_-]/g, "")}`;

  // Single-colour series go inline: no <style> tag, CSP friendly.
  const inlineVars = useMemo(() => {
    const vars: Record<string, string> = {};
    for (const [key, item] of Object.entries(config)) {
      const value = item.color ?? item.theme?.light;
      if (value) vars[`--color-${key}`] = value;
    }
    return vars as CSSProperties;
  }, [config]);

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-slot="chart"
        data-chart={chartId}
        className={cx(chartTokens.tokens, styles.container, className)}
        style={{ ...inlineVars, ...style }}
        {...rest}
      >
        <ChartThemeStyle id={chartId} config={config} />
        <ResponsiveContainer initialDimension={initialDimension}>{children}</ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  );
}

/** Per-preset overrides, only for series that declare `theme`. */
function ChartThemeStyle({ id, config }: { id: string; config: ChartConfig }) {
  const themed = Object.entries(config).filter(([, item]) => item.theme);
  if (!themed.length) return null;

  const blocks = (Object.keys(THEME_SELECTORS) as ThemeName[])
    .filter((theme) => theme !== "light")
    .map((theme) => {
      const lines = themed
        .map(([key, item]) => {
          const value = item.theme?.[theme];
          return value ? `  --color-${key}: ${value};` : null;
        })
        .filter(Boolean)
        .join("\n");
      if (!lines) return "";
      // tokens.css applies a layer as an ancestor attribute or class, and via :has().
      const selectors = THEME_SELECTORS[theme].flatMap((p) => [`${p} [data-chart="${id}"]`, `:root:has(${p}) [data-chart="${id}"]`]);
      return `${selectors.join(", ")} {\n${lines}\n}`;
    })
    .filter(Boolean)
    .join("\n");

  return blocks ? <style dangerouslySetInnerHTML={{ __html: blocks }} /> : null;
}

// ── Tooltip ─────────────────────────────────────────────────────────────

/** Recharts' Tooltip, unchanged (as shadcn exports it). Spread TOOLTIP_MOTION onto it. */
export const ChartTooltip = RechartsTooltip;

type Indicator = "dot" | "line" | "dashed";

export type ChartTooltipContentProps = Omit<
  Partial<TooltipContentProps>,
  "formatter" | "labelFormatter" | "content"
> & {
  className?: string;
  /** dot (default), line or dashed key beside each row. */
  indicator?: Indicator;
  hideLabel?: boolean;
  hideIndicator?: boolean;
  /** Config key to read the label from, when the label is not the x value. */
  labelKey?: string;
  /** Row name from this field of the datum (pies: "browser"). */
  nameKey?: string;
  /** Forces every indicator to one colour. */
  color?: string;
  /** Header text. Receives the resolved label and the payload. */
  labelFormatter?: (label: ReactNode, payload: ReadonlyArray<TooltipPayloadEntry>) => ReactNode;
  /** Replaces a row's whole body. */
  formatter?: (
    value: TooltipPayloadEntry["value"],
    name: TooltipPayloadEntry["name"],
    item: TooltipPayloadEntry,
    index: number,
    datum: unknown,
  ) => ReactNode;
  /** Formats each numeric value (kit default: formatNumber). */
  valueFormatter?: (value: number) => string;
  /** Small uppercase tag beside the label ("Cumulative"). Kit extra. */
  tag?: string;
  /** Adds a total row: stacked charts. Kit extra. */
  total?: boolean | string;
};

/**
 * The tooltip body. Same props and behaviour as shadcn's ChartTooltipContent
 * (indicator, hideLabel, hideIndicator, labelKey, nameKey, labelFormatter,
 * formatter, color), plus the kit's valueFormatter, tag and total.
 */
export function ChartTooltipContent({
  active,
  payload,
  label,
  className,
  indicator = "dot",
  hideLabel = false,
  hideIndicator = false,
  labelKey,
  nameKey,
  color,
  labelFormatter,
  formatter,
  valueFormatter = formatNumber,
  tag,
  total,
}: ChartTooltipContentProps) {
  const { config } = useChart();

  const tooltipLabel = useMemo(() => {
    if (hideLabel || !payload?.length) return null;
    const [item] = payload;
    const key = `${labelKey ?? item?.dataKey ?? item?.name ?? "value"}`;
    const itemConfig = configFromPayload(config, item, key);
    const value: ReactNode =
      !labelKey && (typeof label === "string" || typeof label === "number")
        ? (config[String(label)]?.label ?? label)
        : itemConfig?.label;
    const text = labelFormatter ? labelFormatter(value, payload) : value;
    if (text === null || text === undefined || text === "") return null;
    return (
      <div className={styles.label}>
        {text}
        {tag ? <span className={styles.tag}>{tag}</span> : null}
      </div>
    );
  }, [config, hideLabel, label, labelFormatter, labelKey, payload, tag]);

  if (!active || !payload?.length) return null;

  const rows = payload.filter((item) => item.type !== "none");
  const nestLabel = rows.length === 1 && indicator !== "dot";
  const sum = rows.reduce((n, item) => n + (typeof item.value === "number" ? item.value : 0), 0);

  return (
    <div data-slot="chart-tooltip" className={cx(styles.tooltip, className)}>
      {nestLabel ? null : tooltipLabel}
      <div className={styles.rows}>
        {rows.map((item, index) => {
          const key = `${nameKey ?? item.name ?? item.dataKey ?? "value"}`;
          const itemConfig = configFromPayload(config, item, key);
          const datum = item.payload as Record<string, unknown> | undefined;
          const indicatorColor =
            color ?? (typeof datum?.fill === "string" ? datum.fill : undefined) ?? item.color;

          return (
            <div key={`${key}-${index}`} className={styles.row} data-indicator={indicator}>
              {formatter && item.value !== undefined && item.name !== undefined ? (
                formatter(item.value, item.name, item, index, item.payload)
              ) : (
                <>
                  {itemConfig?.icon ? (
                    <itemConfig.icon />
                  ) : hideIndicator ? null : (
                    <span
                      aria-hidden="true"
                      className={styles.indicator}
                      data-shape={indicator}
                      data-nested={nestLabel && indicator === "dashed" ? "true" : undefined}
                      style={{ "--indicator": indicatorColor } as CSSProperties}
                    />
                  )}
                  <div className={styles.rowBody} data-nested={nestLabel ? "true" : undefined}>
                    <div className={styles.rowText}>
                      {nestLabel ? tooltipLabel : null}
                      <span className={styles.name}>{itemConfig?.label ?? item.name}</span>
                    </div>
                    {item.value !== null && item.value !== undefined ? (
                      <span className={styles.value}>
                        {typeof item.value === "number" ? valueFormatter(item.value) : String(item.value)}
                      </span>
                    ) : null}
                  </div>
                </>
              )}
            </div>
          );
        })}
      </div>
      {total && rows.length > 1 ? (
        <div className={styles.total}>
          <span>{typeof total === "string" ? total : "Total"}</span>
          <span className={styles.value}>{valueFormatter(sum)}</span>
        </div>
      ) : null}
    </div>
  );
}

// ── Legend ──────────────────────────────────────────────────────────────

/** Recharts' Legend, unchanged. Pass content={<ChartLegendContent />}. */
export const ChartLegend = RechartsLegend;

export type ChartLegendContentProps = {
  className?: string;
  hideIcon?: boolean;
  nameKey?: string;
  payload?: ReadonlyArray<LegendPayload>;
  verticalAlign?: "top" | "middle" | "bottom";
};

export function ChartLegendContent({
  className,
  hideIcon = false,
  nameKey,
  payload,
  verticalAlign = "bottom",
}: ChartLegendContentProps) {
  const { config } = useChart();
  if (!payload?.length) return null;

  return (
    <div
      data-slot="chart-legend"
      data-align={verticalAlign === "top" ? "top" : "bottom"}
      className={cx(styles.legend, className)}
    >
      {payload
        .filter((item) => item.type !== "none")
        .map((item) => {
          const key = `${nameKey ?? item.dataKey ?? "value"}`;
          const itemConfig = configFromPayload(config, item, key);
          return (
            <div key={item.value ?? key} className={styles.legendItem}>
              {itemConfig?.icon && !hideIcon ? (
                <itemConfig.icon />
              ) : (
                <span aria-hidden="true" className={styles.legendSwatch} style={{ background: item.color }} />
              )}
              {itemConfig?.label ?? item.value}
            </div>
          );
        })}
    </div>
  );
}

// ── Helpers ─────────────────────────────────────────────────────────────

/** Port of shadcn's getPayloadConfigFromPayload: finds the config entry for a payload item. */
function configFromPayload(config: ChartConfig, item: unknown, key: string) {
  if (typeof item !== "object" || item === null) return undefined;
  const record = item as Record<string, unknown>;
  const inner =
    typeof record.payload === "object" && record.payload !== null
      ? (record.payload as Record<string, unknown>)
      : undefined;

  let configKey = key;
  if (typeof record[key] === "string") configKey = record[key] as string;
  else if (inner && typeof inner[key] === "string") configKey = inner[key] as string;

  return config[configKey] ?? config[key];
}

import { seriesColor } from "./palette";
import type { ChartConfig } from "./primitives";

/** A value column plotted by a chart. */
export type ChartSeries = {
  /** Field on each row. */
  key: string;
  label: string;
  /** For direct end labels, where the full name would crowd the plot. */
  shortLabel?: string;
  /**
   * Fixed categorical slot (0-based). Colour follows the entity, not its
   * position in today's list: give each region or team a stable slot so a
   * filter that removes one never repaints the others. Defaults to index.
   */
  slot?: number;
  /** Explicit colour (a var() from palette.ts). Wins over slot. */
  color?: string;
};

/**
 * shadcn-style config to Rime's series list, for the high-level charts'
 * `config` prop. Order is the categorical slot order. A label that is not a
 * string falls back to the key.
 */
export function seriesFromConfig(config: ChartConfig): ChartSeries[] {
  return Object.entries(config).map(([key, c], slot) => ({
    key,
    label: typeof c.label === "string" ? c.label : key,
    color: c.color ?? c.theme?.light,
    slot,
  }));
}

/**
 * A chart's series, either as Rime's list or as a shadcn ChartConfig.
 * Exactly one is given.
 */
export type SeriesOrConfig =
  | { series: ReadonlyArray<ChartSeries>; config?: never }
  | { config: ChartConfig; series?: never };

export function resolveSeries(p: { series?: ReadonlyArray<ChartSeries>; config?: ChartConfig }): ReadonlyArray<ChartSeries> {
  return p.series ?? (p.config ? seriesFromConfig(p.config) : []);
}

export type ChartRow = Record<string, string | number | null | undefined>;

export function colorOf(series: ChartSeries, index: number): string {
  return series.color ?? seriesColor(series.slot ?? index);
}

export function numberAt(row: ChartRow, key: string): number {
  const v = row[key];
  return typeof v === "number" && Number.isFinite(v) ? v : 0;
}

/**
 * Clean, round axis ticks from zero: 0 / 5 / 10 / 15, 0 / 250 / 500. The
 * charts set their domain from these, so ticks are always whole steps and
 * direct labels can be placed (and collision-checked) before render.
 */
export function niceTicks(max: number, target = 4): number[] {
  if (!(max > 0)) return [0, 1];
  const raw = max / target;
  const magnitude = 10 ** Math.floor(Math.log10(raw));
  const step = [1, 2, 2.5, 5, 10].map((m) => m * magnitude).find((s) => s >= raw) ?? 10 * magnitude;
  // Counts are whole: never a 0.5 tick on a customer axis.
  const whole = max >= target ? Math.max(1, Math.round(step)) : step;
  const top = Math.ceil(max / whole) * whole;
  const ticks: number[] = [];
  for (let v = 0; v <= top + whole / 2; v += whole) ticks.push(Number(v.toFixed(6)));
  return ticks;
}

/** Largest value a chart has to fit: per row, summed when stacked. */
export function maxOf(rows: ReadonlyArray<ChartRow>, series: ReadonlyArray<ChartSeries>, stacked: boolean): number {
  let max = 0;
  for (const row of rows) {
    if (stacked) max = Math.max(max, series.reduce((n, s) => n + numberAt(row, s.key), 0));
    else for (const s of series) max = Math.max(max, numberAt(row, s.key));
  }
  return max;
}

export const OTHER_KEY = "__other";

/**
 * Keep the first `max - 1` series and sum the rest into "Other". Never solve
 * too many series with more hues. Survivors keep their slots, so folding
 * does not repaint them; Other takes the de-emphasis grey.
 */
export function foldSeries(
  rows: ReadonlyArray<ChartRow>,
  series: ReadonlyArray<ChartSeries>,
  max: number,
  otherLabel = "Other",
): { rows: ChartRow[]; series: ChartSeries[] } {
  if (series.length <= max) return { rows: rows.map((r) => ({ ...r })), series: series.map((s, i) => ({ slot: i, ...s })) };
  const kept = series.slice(0, max - 1).map((s, i) => ({ slot: i, ...s }));
  const folded = series.slice(max - 1);
  return {
    rows: rows.map((r) => ({ ...r, [OTHER_KEY]: folded.reduce((n, s) => n + numberAt(r, s.key), 0) })),
    series: [...kept, { key: OTHER_KEY, label: otherLabel, color: "var(--chart-other)" }],
  };
}

import styles from "./Charts.module.css";

export type SparklineProps = {
  values: ReadonlyArray<number>;
  width?: number;
  height?: number;
  /**
   * The history in the de-emphasis hue, the current period (last segment and
   * end dot) in the accent. Set false for an all-accent line.
   */
  emphasiseLast?: boolean;
  /** Accent colour, a var() from palette.ts. */
  color?: string;
  /** Include zero in the scale. On for counts, off for rates that never near it. */
  zeroBased?: boolean;
  className?: string;
};

/**
 * A tiny trend for stat tiles. Plain SVG with no axes, no tooltip and no
 * measuring, so it renders on the server. Decorative: the tile beside it
 * states the value and the change in words.
 */
export function Sparkline({
  values,
  width = 96,
  height = 28,
  emphasiseLast = true,
  color = "var(--chart-1)",
  zeroBased = true,
  className,
}: SparklineProps) {
  if (values.length < 2) return <svg width={width} height={height} aria-hidden="true" className={className} />;

  const pad = 3; // room for the 2px ring round the end dot
  const min = zeroBased ? Math.min(0, ...values) : Math.min(...values);
  const max = Math.max(...values);
  const span = max - min || 1;
  const step = (width - pad * 2) / (values.length - 1);
  const points = values.map((v, i) => [pad + i * step, pad + (1 - (v - min) / span) * (height - pad * 2)] as const);
  const path = (pts: ReadonlyArray<readonly [number, number]>) =>
    pts.map(([x, y], i) => `${i ? "L" : "M"}${x.toFixed(1)} ${y.toFixed(1)}`).join(" ");
  const [ex, ey] = points[points.length - 1];

  return (
    <svg
      className={[styles.tokens, styles.sparkline, className].filter(Boolean).join(" ")}
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      aria-hidden="true"
      focusable="false"
    >
      <path d={path(points)} stroke={emphasiseLast ? "var(--chart-other)" : color} />
      {emphasiseLast ? <path d={path(points.slice(-2))} stroke={color} /> : null}
      <circle cx={ex} cy={ey} r={2.5} fill={color} stroke="var(--chart-gap)" strokeWidth={1.5} />
    </svg>
  );
}

import { TrendingDown, TrendingUp } from "lucide-react";
import type { CSSProperties, ReactNode } from "react";
import { Skeleton } from "@/components/ui/Skeleton/Skeleton";
import { cx } from "@/components/ui/_internal/cx";
import styles from "./Charts.module.css";
import { formatDelta, formatNumber } from "./format";
import { Sparkline } from "./Sparkline";

export type Stat = {
  /** Sentence case, no trailing colon. */
  label: string;
  value: number;
  format?: (value: number) => string;
  /** Small unit after the value ("days"). */
  unit?: string;
  /** Change against a named period. Colour = direction × whether up is good. */
  delta?: {
    value: number;
    /** "vs last week". */
    period: string;
    format?: (value: number) => string;
    /** Turnaround time falls when things improve; orders rise. Default "up". */
    goodWhen?: "up" | "down";
  };
  /** Last n periods, oldest first; the current period is the accent. */
  trend?: ReadonlyArray<number>;
  /** Spoken in place of the sparkline: "Weekly, last 12 weeks: 8 to 32". */
  trendLabel?: string;
  /** Extra line under the value. */
  note?: ReactNode;
};

export type StatStripProps = {
  stats: ReadonlyArray<Stat>;
  loading?: boolean;
  className?: string;
  "aria-label"?: string;
};

/**
 * Headline figures in one row inside one panel, split by hairlines: never a
 * grid of separate cards. Values are proportional figures at display size.
 */
export function StatStrip({ stats, loading, className, "aria-label": ariaLabel }: StatStripProps) {
  const style = { "--stat-count": stats.length } as CSSProperties;
  return (
    <dl className={cx(styles.tokens, styles.strip, className)} style={style} aria-label={ariaLabel} aria-busy={loading || undefined}>
      {stats.map((s) => (
        <div key={s.label} className={styles.stat}>
          <dt className={styles.statLabel}>{s.label}</dt>
          {loading ? (
            <dd className={styles.statSkeleton}>
              <Skeleton width={72} height={28} />
              <span className={styles.statFoot}>
                <Skeleton variant="text" height={10} width={96} />
                {s.trend ? <Skeleton width={96} height={24} /> : null}
              </span>
            </dd>
          ) : (
            <>
              <dd className={styles.statValue}>
                {(s.format ?? formatNumber)(s.value)}
                {s.unit ? <span className={styles.statUnit}>{s.unit}</span> : null}
              </dd>
              <dd className={styles.statFoot}>
                {s.delta ? <Delta {...s.delta} /> : <span />}
                {s.trend ? (
                  <>
                    <Sparkline values={s.trend} zeroBased={s.delta?.goodWhen !== "down"} />
                    {s.trendLabel ? <span className="sr-only">{s.trendLabel}</span> : null}
                  </>
                ) : null}
              </dd>
              {s.note ? <dd className={styles.subtitle}>{s.note}</dd> : null}
            </>
          )}
        </div>
      ))}
    </dl>
  );
}

function Delta({ value, period, format = formatNumber, goodWhen = "up" }: NonNullable<Stat["delta"]>) {
  const flat = value === 0;
  const good = (value > 0 && goodWhen === "up") || (value < 0 && goodWhen === "down");
  const Icon = value > 0 ? TrendingUp : TrendingDown;
  return (
    <span className={cx(styles.delta, flat ? styles.deltaFlat : good ? styles.deltaGood : styles.deltaBad)}>
      {flat ? null : <Icon size={13} strokeWidth={2.4} aria-hidden="true" />}
      {flat ? "No change" : formatDelta(value, format)}
      <span className={styles.deltaPeriod}>{period}</span>
    </span>
  );
}

"use client";

import { Area, CartesianGrid, ComposedChart, LabelList, Line, ReferenceLine, Tooltip, XAxis, YAxis } from "recharts";
import {
  activeDot,
  CATEGORY_AXIS,
  CROSSHAIR,
  endLabel,
  endLabelMargin,
  endLabelsFit,
  GRID,
  VALUE_AXIS,
  X_AXIS_HEIGHT,
  TOOLTIP_MOTION,
} from "./cartesian";
import { ChartFrame, type ChartBaseProps, type LegendItem } from "./ChartFrame";
import { ChartTooltip } from "./ChartTooltip";
import { formatNumber } from "./format";
import { colorOf, maxOf, niceTicks, resolveSeries, type ChartRow, type SeriesOrConfig } from "./scale";

export type TrendChartProps = ChartBaseProps & {
  data: ReadonlyArray<ChartRow>;
  /** Field holding the x value (an ISO date for time series). */
  x: string;
  /** Axis tick: short ("23 Nov"). */
  formatX?: (value: string) => string;
  /** Tooltip header and table rows: in full ("Week of 23 Nov 2026"). */
  formatXLong?: (value: string) => string;
  formatValue?: (value: number) => string;
  /** Table header for the x column. */
  xLabel?: string;
  /**
   * Value and name at each line's end. On by default for up to four series;
   * switched off automatically where the ends would collide.
   */
  endLabels?: boolean;
  /** One horizontal limit on the same axis (program places). Never a second axis. */
  reference?: { value: number; label: string };
  /** Tooltip header tag, e.g. "Cumulative". */
  tooltipTag?: string;
} & SeriesOrConfig;

type Kind = { kind: "line" } | { kind: "area"; stacked?: boolean };

const MARGIN_TOP = 12;

function TrendChart(props: TrendChartProps & Kind) {
  const {
    data,
    x,
    series: seriesProp,
    config,
    formatX = String,
    formatXLong,
    formatValue = formatNumber,
    xLabel = "Week",
    endLabels = true,
    reference,
    tooltipTag,
    height = 248,
    ...base
  } = props;
  const stacked = props.kind === "area" && Boolean(props.stacked);
  const series = resolveSeries({ series: seriesProp, config });

  const dataMax = maxOf(data, series, stacked);
  const ticks = niceTicks(Math.max(dataMax, reference?.value ?? 0));
  const top = ticks[ticks.length - 1];
  const plotHeight = height - MARGIN_TOP - X_AXIS_HEIGHT;
  const showEnds = endLabels && !stacked && endLabelsFit(data, series, top, plotHeight);
  const lastIndex = data.length - 1;
  const yWidth = Math.max(28, formatValue(top).length * 7 + 8);

  const legend: LegendItem[] = series.map((s, i) => ({
    key: s.key,
    label: s.label,
    color: colorOf(s, i),
    shape: props.kind === "line" ? "line" : "rect",
  }));

  return (
    <ChartFrame
      {...base}
      height={height}
      skeleton={props.kind === "line" ? "line" : "area"}
      legend={legend}
      isEmpty={data.length === 0}
      table={{
        rowHeader: { key: x, label: xLabel, format: (v) => (formatXLong ?? formatX)(String(v)) },
        columns: series.map((s) => ({ key: s.key, label: s.label, numeric: true, format: (v) => formatValue(Number(v ?? 0)) })),
        rows: data,
      }}
    >
      {({ width }) => (
        <ComposedChart
          width={width}
          height={height}
          data={data as ChartRow[]}
          margin={{ top: MARGIN_TOP, right: showEnds ? endLabelMargin(series) : 12, bottom: 0, left: 0 }}
          desc={base.summary}
          accessibilityLayer
        >
          <CartesianGrid vertical={false} {...GRID} />
          <XAxis
            dataKey={x}
            {...CATEGORY_AXIS}
            tickFormatter={(v) => formatX(String(v))}
            interval="preserveStartEnd"
            minTickGap={18}
          />
          <YAxis {...VALUE_AXIS} domain={[0, top]} ticks={ticks} width={yWidth} tickFormatter={(v) => formatValue(Number(v))} />
          {reference ? (
            <ReferenceLine
              y={reference.value}
              stroke="var(--chart-cursor)"
              strokeWidth={1}
              label={{
                value: `${reference.label} · ${formatValue(reference.value)}`,
                position: "insideTopLeft",
                fill: "var(--chart-label)",
                fontSize: 11,
                offset: 6,
              }}
            />
          ) : null}
          <Tooltip
            cursor={CROSSHAIR}
            {...TOOLTIP_MOTION}
            content={(p) => (
              <ChartTooltip
                {...p}
                series={series}
                formatLabel={formatXLong ?? formatX}
                formatValue={formatValue}
                tag={tooltipTag}
                total={stacked}
                indicator={props.kind === "line" ? "line" : "dot"}
              />
            )}
          />
          {series.map((s, i) => {
            const color = colorOf(s, i);
            const labels = showEnds ? (
              <LabelList dataKey={s.key} content={endLabel(lastIndex, s.shortLabel ?? s.label, formatValue)} />
            ) : null;
            return props.kind === "line" ? (
              <Line
                key={s.key}
                type="monotone"
                dataKey={s.key}
                name={s.label}
                stroke={color}
                strokeWidth={2}
                strokeLinecap="round"
                strokeLinejoin="round"
                dot={false}
                activeDot={activeDot(color)}
              >
                {labels}
              </Line>
            ) : (
              <Area
                key={s.key}
                type="monotone"
                dataKey={s.key}
                name={s.label}
                stackId={stacked ? "stack" : undefined}
                stroke={color}
                strokeWidth={2}
                fill={color}
                fillOpacity={0.1}
                activeDot={activeDot(color)}
              >
                {labels}
              </Area>
            );
          })}
        </ComposedChart>
      )}
    </ChartFrame>
  );
}

/** Change over time, one or more series. Weekly orders by region. */
export function LineChart(props: TrendChartProps) {
  return <TrendChart {...props} kind="line" />;
}

export type AreaChartProps = TrendChartProps & {
  /** Parts of a whole over time. Off for a single running total. */
  stacked?: boolean;
};

/** A running total, or parts of a whole over time. Fill is a 10% wash, never a block. */
export function AreaChart({ stacked, ...props }: AreaChartProps) {
  return <TrendChart {...props} kind="area" stacked={stacked} />;
}
